import contextlib
import io
import json
import statistics
import sys
import time
from pathlib import Path

repo_root = Path.cwd()
sys.path.insert(0, str(repo_root))
sys.path.insert(0, str(repo_root / 'services/mlx-worker-python'))
sys.path.insert(0, str(repo_root / 'scripts'))

import phase8_metrics_report

embedded_closure_audit = {
    'metrics': {
        'closure_audit.blocker_count': 0.0,
        'closure_audit.accepted_risk_count': 1.0,
        'closure_audit.evidence_gap_count': 0.0,
        'closure_audit.deferred_work_count': 1.0,
    },
    'summary': {
        'top_unresolved_findings': ['Synthetic embedded closure-audit evidence'],
    },
}

elapsed_samples = []
closure_audit_call_samples = []
sample_count = 5

for _ in range(sample_count):
    calls = {'closure_audit': 0}

    phase8_metrics_report.measure_cold_boot_to_ready = lambda repo_root: {'cold_boot_to_ready_ms': 801.2}
    phase8_metrics_report.collect_restart_recovery_evidence = lambda repo_root: {'restart_recovery_ms': 710.7, 'restart_recovery_success_rate': 100.0}
    phase8_metrics_report.collect_runtime_core_evidence = lambda repo_root: {'multi_model_ready_count': 3, 'multi_model_request_success_rate': 100.0}
    phase8_metrics_report.load_release_gate_policy = lambda path: {}
    phase8_metrics_report.collect_operator_action_evidence = lambda jobs_root: {'operator_action_latency_ms': 0.5, 'registry_job_count': 2, 'registry_adapter_count': 1}
    phase8_metrics_report.build_release_gate_report = lambda repo_root, policy, recovery, runtime_core: {
        'install': {'checks': {'manifest_exists': True, 'environment_script_exists': True, 'all_plists_exist': True}},
        'benchmarks': {'report_exists': True, 'metrics': {}},
        'training': {'training_duration_ms': 1420.0, 'adapter_publish_ms': 118.0},
        'recovery': recovery,
        'runtime_core': runtime_core,
        'm9': {
            'summary': {
                'required_probe_count': 23.0,
                'missing_probe_count': 0.0,
                'failed_threshold_count': 0.0,
            },
            'closure_audit': phase8_metrics_report.build_closure_audit(repo_root).to_dict(),
        },
        'passed': True,
        'failures': [],
    }

    class FakeClosureAudit:
        def to_dict(self):
            return embedded_closure_audit

    def tracked_build_closure_audit(repo_root):
        calls['closure_audit'] += 1
        return FakeClosureAudit()

    phase8_metrics_report.build_closure_audit = tracked_build_closure_audit

    started = time.perf_counter()
    original_argv = sys.argv
    try:
        sys.argv = ['phase8_metrics_report.py', '--repo-root', str(repo_root), '--json']
        with contextlib.redirect_stdout(io.StringIO()) as buffer:
            exit_code = phase8_metrics_report.main()
        payload = json.loads(buffer.getvalue())
    finally:
        sys.argv = original_argv

    elapsed_samples.append((time.perf_counter() - started) * 1000.0)
    closure_audit_call_samples.append(float(calls['closure_audit']))
    if exit_code != 0:
        raise SystemExit(f'expected zero exit code, got {exit_code}')
    if payload['closure_audit'] != embedded_closure_audit:
        raise SystemExit('phase8 metrics report did not reuse embedded closure audit payload')

print(json.dumps({
    'elapsed_ms_mean': round(statistics.fmean(elapsed_samples), 6),
    'closure_audit_calls_mean': round(statistics.fmean(closure_audit_call_samples), 6),
    'sample_count': float(sample_count),
}, sort_keys=True))
